workshops:[{date:{pt:"5 dezembro · 09:00–11:30",en:"5 December · 09:00–11:30"},title:{pt:"SILÊNCIO",en:"SILENCE"},subtitle:"José Luís Nunes Martins",venue:{pt:"Capela do Seminário da Torre d’Águilha",en:"Torre d’Águilha Seminary Chapel"},price:"39 €",description:{pt:"Uma manhã para parar, escutar e reencontrar paz. Uma experiência de interioridade aberta a pessoas de diferentes tradições, a quem procura espiritualidade, paz ou sentido e a quem simplesmente precisa de parar.",en:"A morning to pause, listen and rediscover peace. An inner experience open to people from different traditions, to anyone seeking spirituality, peace or meaning, and to those who simply need to pause."},image:A+"oficina_silencio.png",ticketUrl:T},
{date:{pt:"6 dezembro · 16:00–17:30",en:"6 December · 16:00–17:30"},title:{pt:"Constelações Familiares segundo Bert Hellinger",en:"Family Constellations according to Bert Hellinger"},subtitle:"Paula Matos",venue:"STELLA Hall",price:"29 €",image:A+"paula_matos_constelacoes.png",ticketUrl:T},
{date:{pt:"8 dezembro · 10:00–11:00",en:"8 December · 10:00–11:00"},title:{pt:"Workshop de Introdução à Meditação Budista",en:"Introduction to Buddhist Meditation Workshop"},subtitle:{pt:"com Kelsang Khacho",en:"with Kelsang Khacho"},venue:"STELLA Hall · Torre d’Águilha · Cascais",price:"5 €",description:{pt:"Com a orientação da monja budista Kelsang Khacho, do Centro de Meditação Kadampa Deuachen, em Sintra, este workshop propõe uma introdução simples e acessível à meditação budista. Ao longo de 60 minutos, vamos experimentar técnicas de meditação que ajudam a acalmar a mente, cultivar a paz interior e desenvolver um coração mais bondoso, levando esses benefícios para a vida quotidiana e para as relações com os outros. É um encontro prático, aberto a todos, independentemente da religião, crenças ou experiência anterior, com espaço para esclarecer dúvidas. Capacidade máxima: 100 pessoas. Também será possível adquirir entrada no próprio dia, mediante a disponibilidade da sala.",en:"Guided by Buddhist nun Kelsang Khacho from Kadampa Deuachen Meditation Centre in Sintra, this workshop offers a simple and accessible introduction to Buddhist meditation. During 60 minutes, participants will experience meditation techniques that help calm the mind, cultivate inner peace and develop a kinder heart, bringing these benefits into daily life and relationships with others. This practical session is open to everyone, regardless of religion, beliefs or previous experience, and includes time for questions. Maximum capacity: 100 people. Tickets may also be purchased on the day, subject to room availability."},image:B+"workshops/kelsang-khacho-meditacao-budista.jpg",ticketUrl:T}],
